import { useEffect, useEffectEvent, useState } from "react";

export function DraftEditor({ docId }: { docId: string }) {
  const [draft, setDraft] = useState("");

  // Fired by the timer: reads the latest draft, never restarts it
  const onTick = useEffectEvent((id: string) => {
    saveDraft(id, draft);
  });

  useEffect(() => {
    const timer = setInterval(() => onTick(docId), 30_000);
    return () => clearInterval(timer);
  }, [docId]); // typing can't reset the timer

  return <textarea value={draft} onChange={(e) => setDraft(e.target.value)} />;
}
